css:
:root, html, body, gradio-app, .gradio-container {
    background: #ffffff !important;
    color: #0f172a !important;
    color-scheme: light !important;
}
html.dark, html[data-theme="dark"] {
    background: #ffffff !important;
    color: #0f172a !important;
}
/* Standard sans-serif everywhere — but DO NOT override inline span colors,
   which the legend uses for class color swatches. */
.prose, .markdown, h1, h2, h3, h4, h5, p, td, th, label {
    font-family: system-ui, Arial, Helvetica, sans-serif !important;
}
/* Default text color for elements WITHOUT an inline style="color:..." */
.prose:not([style*="color"]),
.markdown p:not([style*="color"]),
h1:not([style*="color"]),
h2:not([style*="color"]),
h3:not([style*="color"]),
h4:not([style*="color"]),
h5:not([style*="color"]),
label:not([style*="color"]) {
    color: #0f172a;
}
code, pre {
    background: #f1f5f9 !important;
    color: #0f172a !important;
}

js:
() => {
    const url = new URL(window.location);
    if (url.searchParams.get('__theme') !== 'light') {
        url.searchParams.set('__theme', 'light');
        window.location.replace(url.toString());
        return;
    }
    document.documentElement.classList.remove('dark');
    document.documentElement.style.colorScheme = 'light';
    document.documentElement.dataset.theme = 'light';
    document.documentElement.style.background = '#ffffff';
    if (document.body) {
        document.body.style.background = '#ffffff';
        document.body.style.color = '#0f172a';
    }
}
